// Supplier API service (generated by engineering-platform Generic Module Generator)
// All HTTP through the Platform Request Client — no raw axios/fetch.
import { http } from './request';
import type { Supplier, SupplierCreateRequest, SupplierUpdateRequest, SupplierQuery, SupplierPageResponse } from '../types/supplier';
import type { EntityId } from '../types/enterprise';

export const supplierApi = {
  page: (query: SupplierQuery = {}) =>
    http.get<SupplierPageResponse>('/supplier' + queryString(query as unknown as Record<string, unknown>)),
  detail: (id: EntityId) => http.get<Supplier>('/supplier/' + id),
  create: (body: SupplierCreateRequest) => http.post<Supplier>('/supplier', body),
  update: (id: EntityId, body: SupplierUpdateRequest) => http.put<Supplier>('/supplier/' + id, body),
  disable: (id: EntityId) => http.post<Supplier>('/supplier/' + id + '/disable', {}),
};

function queryString(params: Record<string, unknown>): string {
  const entries = Object.entries(params).filter(([, v]) => v !== undefined && v !== null && v !== '');
  if (entries.length === 0) return '';
  return '?' + entries.map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(String(v))).join('&');
}
